package br.com.sussmartcare.telemetry.application;
import br.com.sussmartcare.telemetry.domain.*; import br.com.sussmartcare.telemetry.infrastructure.*; import br.com.sussmartcare.telemetry.infrastructure.outbox.EventOutbox; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*;
@Service public class TelemetryApplicationService { private final DeviceRepository devices; private final TelemetrySessionRepository sessions; private final BiometricObservationRepository observations; private final EventOutbox outbox; public TelemetryApplicationService(DeviceRepository d,TelemetrySessionRepository s,BiometricObservationRepository o,EventOutbox out){devices=d;sessions=s;observations=o;outbox=out;} @Transactional public MedicalDevice register(String external,String type,String manufacturer,String model){if(devices.findByExternalId(external).isPresent()) throw new IllegalArgumentException("Dispositivo já registrado");return devices.save(new MedicalDevice(external,type,manufacturer,model));} @Transactional public TelemetrySession start(UUID patient,UUID visit,UUID preHospital,String context){return sessions.save(new TelemetrySession(patient,visit,preHospital,context));} @Transactional public BiometricObservation ingest(UUID sessionId,UUID deviceId,String type,Double value,String unit,Instant measuredAt){var s=sessions.findById(sessionId).orElseThrow(()->new IllegalArgumentException("Sessão não encontrada"));var d=devices.findById(deviceId).orElseThrow(()->new IllegalArgumentException("Dispositivo não encontrado"));if(d.getStatus()!=DeviceStatus.ACTIVE) throw new IllegalStateException("Dispositivo não está ativo");var o=observations.save(new BiometricObservation(sessionId,deviceId,normalize(type),value,normalizeUnit(unit),measuredAt==null?Instant.now():measuredAt,s.getSourceContext()));outbox.append("biometric-observation-received",sessionId.toString(),new ObservationEvent(o.getId(),s.getPatientId(),s.getVisitId(),o.getType(),o.getValue(),o.getUnit(),o.getMeasuredAt(),s.getSourceContext()));return o;} private String normalize(String t){return t.trim().toUpperCase().replace(' ','_');} private String normalizeUnit(String u){return u==null?null:u.trim();} public record ObservationEvent(UUID observationId,UUID patientId,UUID visitId,String type,Double value,String unit,Instant measuredAt,String sourceContext){} }
